int n, m, k;
vector<int> x, y;
vector<pt> ps;

inline bool read() {
	if(!(cin >> n >> m >> k))
		return false;
	x.resize(n);
	fore (i, 0, n)
		cin >> x[i];
	y.resize(m);
	fore (i, 0, m)
		cin >> y[i];
	ps.resize(k);
	fore (i, 0, k)
		cin >> ps[i].x >> ps[i].y;

	return true;
}

inline void solve() {
	li ans = 0;

	fore (_i, 0, 2) {
		vector<int> cntY(m, 0);
		sort(all(ps));

		vector<pt> bord(k);

		int u = 0;
		while (u < k) {
			int v = u;
			while (v < k && ps[v].x == ps[u].x)
				v++;

			fore (i, u, v) {
				int r = int(lower_bound(all(y), ps[i].y) - y.begin());
				int l = r;
				if (y[l] > ps[i].y)
					l--;
				assert(y[l] <= ps[i].y && ps[i].y <= y[r]);

				bord[i] = {l, r};
			}

			fore (i, u, v) if (bord[i].x < bord[i].y)
				ans += cntY[bord[i].x];

			fore (i, u, v) if (bord[i].x < bord[i].y)
				cntY[bord[i].x]++;

			u = v;
		}


		fore (i, 0, k)
			swap(ps[i].x, ps[i].y);
		swap(x, y);
		swap(n, m);
	}

	cout << ans << endl;
}

